import{s as e}from"./pplx-icons-Bk_3cWR9.js";import{t}from"./buildPage-DWQZYYcs.js";var n=t({slug:`alumni-connections`,heroTitle:`Land a job at your dream company in minutes`,heroSubtitle:`Optimize your resume, tailor your cover letter, find alumni connections, and more with Perplexity Computer`,heroCta:`Find my connections`,hasInputUrl:!1,multiFieldInputs:[{name:`school`,label:`School name`,icon:e(`school`),displayCasing:`title`},{name:`company`,label:`Dream company`,icon:e(`building`),displayCasing:`title`},{name:`email`,label:`Email`,icon:e(`mail`),type:`email`}],multiFieldCta:`Find my connections`,multiFieldPrefill:`I'm a student at {school} looking to connect with alumni who work or have worked at {company}. My email is {email}. Research {company}'s career page, LinkedIn presence, and organizational structure. Then search for alumni connections — people who attended {school} and currently work at {company} or recently left. For each alumni contact found, identify their name, current role, department, seniority level, and any shared affiliations (clubs, majors, Greek life, sports teams). Build me a curated outreach dashboard as a web app deployed to a live URL that includes: 1) A ranked list of alumni contacts organized by relevance — prioritizing those in roles aligned with common entry-level paths, recent hires, and people active on LinkedIn, 2) A company overview section covering culture, hiring trends, recent news, and departments currently growing, 3) Personalized outreach message templates for each contact — cold LinkedIn connection requests, informational interview emails, and follow-up messages — all written in a professional but approachable student tone, 4) Talking points for each contact based on their role, background, and shared school affiliations, 5) A networking tracker where I can log outreach status (sent, responded, scheduled, completed) for each contact, 6) A timeline with recommended outreach cadence and follow-up reminders.`,heroOverlaySteps:[`Updating your resume and LinkedIn profile to highlight relevant skills`,`Finding alumni from your school who work at this company`,`Crafting personalized outreach messages and drafting applications`,`Organizing your contacts, tracking conversations, and sending follow-ups`],generatingTitle:`Landing your dream job...`,generatingSteps:[`Matching your {school} profile, academic background, and work experience to open roles`,`Helping you discover and evaluate opportunities at {company} aligned with your goals`,`Drafting personalized outreach messages, cover letters and interview responses`,`Preparing your dedicated career wingman to support you through every step`],featureSectionTitle:`From dream company to warm introductions`,featureCardTitles:[`Connects to your productivity stack`,`Outputs you can send today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Gmail, Google Docs, Slack — Computer organizes your contacts, drafts outreach emails, and tracks responses across the tools you already use.`,`Ranked alumni contact list. Personalized LinkedIn messages. Informational interview email templates. Role-specific talking points. Networking tracker with follow-up cadence.`],capabilitySectionTitle:`Your career advisor, on autopilot`,capabilitySectionSubtitle:`Enter your dream company, step away, get back a complete alumni connections plan.`,capabilityCards:[{title:`Alumni Discovery`,description:`Computer can research your target company and find alumni from your school — current employees, recent hires, and key contacts across departments.`},{title:`Company Intelligence`,description:`Computer can analyze hiring trends, team structure, company culture, and recent news — so you walk into every conversation informed.`},{title:`Outreach Templates`,description:`Computer can generate personalized connection requests, informational interview emails, and follow-up messages — tailored to each contact's role and shared affiliations.`},{title:`Connect Your Tools`,description:`Computer can sync contacts to Google Sheets, draft emails in Gmail, organize notes in Notion, and send reminders to Slack — build workflows across your entire stack.`},{title:`Remembers Your Network`,description:`Computer can track who you've contacted, what they said, and which conversations led to referrals — so every follow-up builds on what came before.`},{title:`New Hire Alerts`,description:`Computer can monitor your target company for new alumni hires, open roles, and recruiting events — and notify you when new networking opportunities appear.`}],signin:{title:`Get your dream role at {company}`,image:`https://r2cdn.perplexity.ai/computer-landing/computer-sign-in-hero.png`,features:[{icon:e(`users`),text:`Find {school} alumni who work at {company}`},{icon:e(`file-text`),text:`Generate personalized cover letters`},{icon:e(`briefcase`),text:`Find jobs that match your skills`},{icon:e(`messages`),text:`Prep for company-specific interviews`}]},placeholderDefaults:{school:`your school`,company:`your dream company`},campaign:{initiateEndpoint:`/rest/marketing/send_alumni_email`,workflow:`alumni-finder`,workflowParams:[`school`,`company`],emailSentTitle:`Check your email for your career dashboard`,emailSentBody:`We found {school} alumni at {company}. In the meantime, see what else Computer can do for you.`}});export{n as default};
